22	enum Mode {
23	    Default(String),
24	    Echo(Vec<String>),
25	    InputRange(RangeInclusive<usize>),
26	}
27	
28	static USAGE: &str = help_usage!("shuf.md");
29	static ABOUT: &str = help_about!("shuf.md");
30	
31	struct Options {
32	    head_count: usize,
33	    output: Option<String>,
34	    random_source: Option<String>,
35	    repeat: bool,
36	    sep: u8,
37	}
38	
39	mod options {
40	    pub static ECHO: &str = "echo";
41	    pub static INPUT_RANGE: &str = "input-range";
42	    pub static HEAD_COUNT: &str = "head-count";
43	    pub static OUTPUT: &str = "output";
44	    pub static RANDOM_SOURCE: &str = "random-source";
45	    pub static REPEAT: &str = "repeat";
46	    pub static ZERO_TERMINATED: &str = "zero-terminated";
47	    pub static FILE_OR_ARGS: &str = "file-or-args";
48	}
