50	#[uucore::main]
51	pub fn uumain(args: impl uucore::Args) -> UResult<()> {
52	    let matches = uu_app().try_get_matches_from(args)?;
53	
54	    let mode = if matches.get_flag(options::ECHO) {
55	        Mode::Echo(
56	            matches
57	                .get_many::<String>(options::FILE_OR_ARGS)
58	                .unwrap_or_default()
59	                .map(String::from)
60	                .collect(),
61	        )
62	    } else if let Some(range) = matches.get_one::<String>(options::INPUT_RANGE) {
63	        match parse_range(range) {
64	            Ok(m) => Mode::InputRange(m),
65	            Err(msg) => {
66	                return Err(USimpleError::new(1, msg));
67	            }
68	        }
69	    } else {
70	        let mut operands = matches
71	            .get_many::<String>(options::FILE_OR_ARGS)
72	            .unwrap_or_default();
73	        let file = operands.next().cloned().unwrap_or("-".into());
74	        if let Some(second_file) = operands.next() {
75	            return Err(UUsageError::new(
76	                1,
77	                format!("unexpected argument '{second_file}' found"),
78	            ));
79	        };
80	        Mode::Default(file)
81	    };
82	
83	    let options = Options {
84	        head_count: {
85	            let headcounts = matches
86	                .get_many::<String>(options::HEAD_COUNT)
87	                .unwrap_or_default()
88	                .cloned()
89	                .collect();
90	            match parse_head_count(headcounts) {
91	                Ok(val) => val,
92	                Err(msg) => return Err(USimpleError::new(1, msg)),
93	            }
94	        },
95	        output: matches.get_one::<String>(options::OUTPUT).map(String::from),
96	        random_source: matches
97	            .get_one::<String>(options::RANDOM_SOURCE)
98	            .map(String::from),
99	        repeat: matches.get_flag(options::REPEAT),
100	        sep: if matches.get_flag(options::ZERO_TERMINATED) {
101	            0x00_u8
102	        } else {
103	            0x0a_u8
104	        },
105	    };
106	
107	    if options.head_count == 0 {
108	        // Do not attempt to read the random source or the input file.
109	        // However, we must touch the output file, if given:
110	        if let Some(s) = options.output {
111	            File::create(&s[..])
112	                .map_err_context(|| format!("failed to open {} for writing", s.quote()))?;
113	        }
114	        return Ok(());
115	    }
116	
117	    match mode {
118	        Mode::Echo(args) => {
119	            let mut evec = args.iter().map(String::as_bytes).collect::<Vec<_>>();
120	            find_seps(&mut evec, options.sep);
121	            shuf_exec(&mut evec, options)?;
122	        }
123	        Mode::InputRange(mut range) => {
124	            shuf_exec(&mut range, options)?;
125	        }
126	        Mode::Default(filename) => {
127	            let fdata = read_input_file(&filename)?;
128	            let mut fdata = vec![&fdata[..]];
129	            find_seps(&mut fdata, options.sep);
130	            shuf_exec(&mut fdata, options)?;
131	        }
132	    }
133	
134	    Ok(())
135	}
