137	pub fn uu_app() -> Command {
138	    Command::new(uucore::util_name())
139	        .about(ABOUT)
140	        .version(crate_version!())
141	        .override_usage(format_usage(USAGE))
142	        .infer_long_args(true)
143	        .arg(
144	            Arg::new(options::ECHO)
145	                .short('e')
146	                .long(options::ECHO)
147	                .help("treat each ARG as an input line")
148	                .action(clap::ArgAction::SetTrue)
149	                .overrides_with(options::ECHO)
150	                .conflicts_with(options::INPUT_RANGE),
151	        )
152	        .arg(
153	            Arg::new(options::INPUT_RANGE)
154	                .short('i')
155	                .long(options::INPUT_RANGE)
156	                .value_name("LO-HI")
157	                .help("treat each number LO through HI as an input line")
158	                .conflicts_with(options::FILE_OR_ARGS),
159	        )
160	        .arg(
161	            Arg::new(options::HEAD_COUNT)
162	                .short('n')
163	                .long(options::HEAD_COUNT)
164	                .value_name("COUNT")
165	                .action(clap::ArgAction::Append)
166	                .help("output at most COUNT lines"),
167	        )
168	        .arg(
169	            Arg::new(options::OUTPUT)
170	                .short('o')
171	                .long(options::OUTPUT)
172	                .value_name("FILE")
173	                .help("write result to FILE instead of standard output")
174	                .value_hint(clap::ValueHint::FilePath),
175	        )
176	        .arg(
177	            Arg::new(options::RANDOM_SOURCE)
178	                .long(options::RANDOM_SOURCE)
179	                .value_name("FILE")
180	                .help("get random bytes from FILE")
181	                .value_hint(clap::ValueHint::FilePath),
182	        )
183	        .arg(
184	            Arg::new(options::REPEAT)
185	                .short('r')
186	                .long(options::REPEAT)
187	                .help("output lines can be repeated")
188	                .action(ArgAction::SetTrue)
189	                .overrides_with(options::REPEAT),
190	        )
191	        .arg(
192	            Arg::new(options::ZERO_TERMINATED)
193	                .short('z')
194	                .long(options::ZERO_TERMINATED)
195	                .help("line delimiter is NUL, not newline")
196	                .action(ArgAction::SetTrue)
197	                .overrides_with(options::ZERO_TERMINATED),
198	        )
199	        .arg(
200	            Arg::new(options::FILE_OR_ARGS)
201	                .action(clap::ArgAction::Append)
202	                .value_hint(clap::ValueHint::FilePath),
203	        )
204	}
