206	fn read_input_file(filename: &str) -> UResult<Vec<u8>> {
207	    let mut file = BufReader::new(if filename == "-" {
208	        Box::new(stdin()) as Box<dyn Read>
209	    } else {
210	        let file = File::open(filename)
211	            .map_err_context(|| format!("failed to open {}", filename.quote()))?;
212	        Box::new(file) as Box<dyn Read>
213	    });
214	
215	    let mut data = Vec::new();
216	    file.read_to_end(&mut data)
217	        .map_err_context(|| format!("failed reading {}", filename.quote()))?;
218	
219	    Ok(data)
